{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://halcyon-threshold.pagewell.app/schema/threshold-record-v0.1.schema.json",
  "title": "Threshold Record",
  "description": "Draft schema for an advanced-AI incident or near-miss learning record. Structural validity does not establish truth, completeness, safety, legal compliance, or causality. Never place personal data, secrets, dangerous procedural detail, or unauthorized material in a record.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "spec_version",
    "record_id",
    "record_revision",
    "record_status",
    "event_type",
    "created_at",
    "updated_at",
    "summary",
    "times",
    "system",
    "actual_effects",
    "potential_effects",
    "observations",
    "material_unknowns",
    "severity",
    "response_status",
    "evidence",
    "contributing_factors",
    "corrective_actions",
    "disclosure",
    "revision_history"
  ],
  "properties": {
    "spec_version": { "const": "0.1.0" },
    "record_id": {
      "type": "string",
      "pattern": "^tr_[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$",
      "description": "Random identifier; do not encode names, organizations, dates, or incident details."
    },
    "record_revision": { "type": "integer", "minimum": 1 },
    "record_status": { "enum": ["draft", "active", "under_review", "closed"] },
    "event_type": {
      "enum": ["incident", "near_miss"],
      "description": "Use near_miss only when no actual harm is asserted; use incident when actual harm and an avoided pathway both exist."
    },
    "created_at": { "type": "string", "format": "date-time" },
    "updated_at": { "type": "string", "format": "date-time" },
    "next_update_at": { "type": "string", "format": "date-time" },
    "summary": {
      "type": "string",
      "minLength": 20,
      "maxLength": 5000,
      "description": "Non-sensitive factual summary. Avoid personal data and dangerous operational detail."
    },
    "times": {
      "type": "object",
      "additionalProperties": false,
      "required": ["time_precision"],
      "properties": {
        "occurred_at": { "type": "string", "format": "date-time" },
        "occurred_end_at": { "type": "string", "format": "date-time" },
        "detected_at": { "type": "string", "format": "date-time" },
        "reported_at": { "type": "string", "format": "date-time" },
        "contained_at": { "type": "string", "format": "date-time" },
        "time_precision": { "enum": ["exact", "second", "minute", "hour", "day", "range", "estimated", "unknown"] },
        "notes": { "type": "string", "maxLength": 2000 }
      }
    },
    "system": {
      "type": "object",
      "additionalProperties": false,
      "required": ["model_reference", "deployment_reference", "identification_limits"],
      "properties": {
        "model_reference": { "type": "string", "minLength": 1, "maxLength": 500 },
        "model_revision": { "type": "string", "maxLength": 500 },
        "deployment_reference": { "type": "string", "minLength": 1, "maxLength": 500 },
        "configuration_reference": { "type": "string", "maxLength": 500 },
        "tool_permissions": {
          "type": "array",
          "items": { "type": "string", "maxLength": 300 },
          "maxItems": 100
        },
        "safeguards": {
          "type": "array",
          "items": { "type": "string", "maxLength": 500 },
          "maxItems": 100
        },
        "identification_limits": { "type": "string", "minLength": 1, "maxLength": 2000 }
      }
    },
    "actual_effects": {
      "type": "array",
      "items": { "$ref": "#/$defs/effect" },
      "description": "Observed effects only; empty for a pure near miss."
    },
    "potential_effects": {
      "type": "array",
      "items": { "$ref": "#/$defs/effect" },
      "description": "Plausible avoided or unrealized effects; never merge into actual impact."
    },
    "affected_categories": {
      "type": "array",
      "items": { "type": "string", "maxLength": 200 },
      "description": "Broad categories only; avoid identifying individuals or small vulnerable groups."
    },
    "observations": {
      "type": "array",
      "minItems": 1,
      "items": { "$ref": "#/$defs/observation" }
    },
    "material_unknowns": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["unknown_id", "statement", "resolution_plan"],
        "properties": {
          "unknown_id": { "type": "string", "pattern": "^u_[A-Za-z0-9_-]+$" },
          "statement": { "type": "string", "minLength": 1, "maxLength": 2000 },
          "resolution_plan": { "type": "string", "minLength": 1, "maxLength": 2000 },
          "due_at": { "type": "string", "format": "date-time" }
        }
      }
    },
    "severity": {
      "type": "object",
      "additionalProperties": false,
      "required": ["level", "status", "rationale"],
      "properties": {
        "level": { "enum": ["critical", "high", "medium", "low", "unknown"] },
        "status": { "const": "provisional" },
        "rationale": { "type": "string", "minLength": 10, "maxLength": 3000 },
        "review_at": { "type": "string", "format": "date-time" }
      }
    },
    "response_status": {
      "enum": ["not_started", "in_progress", "contained", "monitoring", "closed", "unknown"]
    },
    "immediate_response": {
      "type": "array",
      "items": { "type": "string", "maxLength": 2000 }
    },
    "responsible_contact_role": {
      "type": "string",
      "maxLength": 300,
      "description": "Role or controlled contact alias, not an individual's personal details."
    },
    "evidence": {
      "type": "array",
      "items": { "$ref": "#/$defs/evidence" },
      "description": "References and integrity metadata only; not raw sensitive evidence."
    },
    "contributing_factors": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["factor_id", "statement", "status", "supporting_evidence", "disconfirming_evidence"],
        "properties": {
          "factor_id": { "type": "string", "pattern": "^f_[A-Za-z0-9_-]+$" },
          "statement": { "type": "string", "minLength": 1, "maxLength": 2000 },
          "status": { "enum": ["hypothesized", "supported", "refuted", "unknown"] },
          "supporting_evidence": { "type": "array", "items": { "type": "string", "pattern": "^e_[A-Za-z0-9_-]+$" }, "uniqueItems": true },
          "disconfirming_evidence": { "type": "array", "items": { "type": "string", "pattern": "^e_[A-Za-z0-9_-]+$" }, "uniqueItems": true },
          "alternative_explanation": { "type": "string", "maxLength": 2000 }
        }
      }
    },
    "disagreements": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["topic", "positions", "resolution_status"],
        "properties": {
          "topic": { "type": "string", "maxLength": 1000 },
          "positions": { "type": "array", "minItems": 2, "items": { "type": "string", "maxLength": 1000 } },
          "resolution_status": { "enum": ["open", "narrowed", "resolved"] }
        }
      }
    },
    "corrective_actions": {
      "type": "array",
      "items": { "$ref": "#/$defs/action" }
    },
    "disclosure": {
      "type": "object",
      "additionalProperties": false,
      "required": ["classification", "public_release", "redactions", "review_notes"],
      "properties": {
        "classification": { "enum": ["public_summary", "regulator_confidential", "restricted"] },
        "public_release": { "type": "boolean" },
        "redactions": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["location", "reason"],
            "properties": {
              "location": { "type": "string", "maxLength": 500 },
              "reason": { "enum": ["personal_data", "security", "confidential", "legal", "unknown"] }
            }
          }
        },
        "review_notes": { "type": "string", "maxLength": 3000 }
      }
    },
    "revision_history": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["revision", "changed_at", "reason"],
        "properties": {
          "revision": { "type": "integer", "minimum": 1 },
          "changed_at": { "type": "string", "format": "date-time" },
          "reason": { "type": "string", "minLength": 1, "maxLength": 2000 }
        }
      }
    }
  },
  "allOf": [
    {
      "if": {
        "properties": { "event_type": { "const": "near_miss" } },
        "required": ["event_type"]
      },
      "then": {
        "properties": {
          "actual_effects": { "maxItems": 0 },
          "potential_effects": { "minItems": 1 }
        }
      }
    },
    {
      "if": {
        "properties": { "event_type": { "const": "incident" } },
        "required": ["event_type"]
      },
      "then": {
        "properties": { "actual_effects": { "minItems": 1 } }
      }
    },
    {
      "if": {
        "properties": { "record_status": { "const": "closed" } },
        "required": ["record_status"]
      },
      "then": {
        "required": ["responsible_contact_role"],
        "properties": {
          "response_status": { "const": "closed" },
          "material_unknowns": {
            "description": "Closure may coexist with unknowns, but each must retain an explicit resolution or acceptance plan."
          }
        }
      }
    }
  ],
  "$defs": {
    "effect": {
      "type": "object",
      "additionalProperties": false,
      "required": ["effect_id", "statement", "confidence", "evidence_refs"],
      "properties": {
        "effect_id": { "type": "string", "pattern": "^(a|p)_[A-Za-z0-9_-]+$" },
        "statement": { "type": "string", "minLength": 1, "maxLength": 2000 },
        "confidence": { "enum": ["confirmed", "high", "moderate", "low", "unknown"] },
        "evidence_refs": { "type": "array", "items": { "type": "string", "pattern": "^e_[A-Za-z0-9_-]+$" }, "uniqueItems": true }
      }
    },
    "observation": {
      "type": "object",
      "additionalProperties": false,
      "required": ["observation_id", "statement", "claim_type", "confidence", "evidence_refs"],
      "properties": {
        "observation_id": { "type": "string", "pattern": "^o_[A-Za-z0-9_-]+$" },
        "statement": { "type": "string", "minLength": 1, "maxLength": 2000 },
        "claim_type": { "enum": ["observed", "inferred", "unknown"] },
        "confidence": { "enum": ["confirmed", "high", "moderate", "low", "unknown"] },
        "evidence_refs": { "type": "array", "items": { "type": "string", "pattern": "^e_[A-Za-z0-9_-]+$" }, "uniqueItems": true }
      }
    },
    "evidence": {
      "type": "object",
      "additionalProperties": false,
      "required": ["evidence_id", "description", "kind", "collected_at", "availability", "access", "retrieval_role", "limitations"],
      "properties": {
        "evidence_id": { "type": "string", "pattern": "^e_[A-Za-z0-9_-]+$" },
        "description": { "type": "string", "minLength": 1, "maxLength": 1000 },
        "kind": { "enum": ["system_log", "tool_trace", "model_output", "evaluation_result", "configuration", "operator_report", "affected_party_report", "financial_record", "test_result", "other"] },
        "collected_at": { "type": "string", "format": "date-time" },
        "availability": { "enum": ["available", "partial", "expired", "not_collected", "unknown"] },
        "access": { "enum": ["public", "regulator_confidential", "restricted", "unavailable"] },
        "retrieval_role": { "type": "string", "minLength": 1, "maxLength": 300 },
        "retention_until": { "type": "string", "format": "date-time" },
        "digest": {
          "type": "object",
          "additionalProperties": false,
          "required": ["algorithm", "value"],
          "properties": {
            "algorithm": { "enum": ["SHA-256", "SHA-384", "SHA-512"] },
            "value": { "type": "string", "pattern": "^[0-9a-fA-F]+$", "minLength": 64, "maxLength": 128 }
          }
        },
        "limitations": { "type": "string", "minLength": 1, "maxLength": 2000 }
      }
    },
    "action": {
      "type": "object",
      "additionalProperties": false,
      "required": ["action_id", "description", "owner_role", "status", "verification"],
      "properties": {
        "action_id": { "type": "string", "pattern": "^c_[A-Za-z0-9_-]+$" },
        "description": { "type": "string", "minLength": 1, "maxLength": 2000 },
        "owner_role": { "type": "string", "minLength": 1, "maxLength": 300 },
        "due_at": { "type": "string", "format": "date-time" },
        "status": { "enum": ["proposed", "in_progress", "implemented", "verified", "rejected", "abandoned"] },
        "status_rationale": { "type": "string", "maxLength": 2000 },
        "verification": {
          "type": "object",
          "additionalProperties": false,
          "required": ["method", "scope", "result", "residual_risk", "evidence_refs"],
          "properties": {
            "method": { "type": "string", "minLength": 1, "maxLength": 2000 },
            "scope": { "type": "string", "minLength": 1, "maxLength": 2000 },
            "checked_at": { "type": "string", "format": "date-time" },
            "result": { "enum": ["effective", "ineffective", "inconclusive", "pending", "not_applicable"] },
            "residual_risk": { "type": "string", "minLength": 1, "maxLength": 2000 },
            "evidence_refs": { "type": "array", "items": { "type": "string", "pattern": "^e_[A-Za-z0-9_-]+$" }, "uniqueItems": true }
          }
        }
      },
      "allOf": [
        {
          "if": {
            "properties": { "status": { "const": "verified" } },
            "required": ["status"]
          },
          "then": {
            "properties": {
              "verification": {
                "required": ["checked_at"],
                "properties": { "result": { "enum": ["effective", "ineffective", "inconclusive"] } }
              }
            }
          }
        }
      ]
    }
  }
}

@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700&family=Newsreader:ital,opsz,wght@1,6..72,400;1,6..72,500&display=swap');

:root {
  --ink: #142b2a;
  --muted: #526461;
  --paper: #f7f8f3;
  --white: #ffffff;
  --line: #d9dfd7;
  --green: #165e50;
  --green-dark: #0b4037;
  --mint: #dcebe0;
  --lime: #d5e7a7;
  --code: #102f2c;
  --max: 1160px;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  color: var(--ink);
  background: var(--paper);
  font-family: Manrope, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 17px;
  line-height: 1.65;
  -webkit-font-smoothing: antialiased;
}
a { color: var(--green); text-underline-offset: 4px; }
a:hover { color: var(--green-dark); }
a:focus-visible, summary:focus-visible, [tabindex]:focus-visible {
  outline: 3px solid #8b5cf6;
  outline-offset: 4px;
}
.wrap { width: min(calc(100% - 48px), var(--max)); margin-inline: auto; }
.skip { position: absolute; left: 12px; top: -100px; background: var(--white); padding: 12px; z-index: 20; }
.skip:focus { top: 12px; }
.site-header {
  min-height: 88px;
  padding: 18px max(24px, calc((100vw - var(--max)) / 2));
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
  border-bottom: 1px solid var(--line);
  background: rgba(247, 248, 243, .96);
}
.brand { display: inline-flex; gap: 12px; align-items: center; color: var(--ink); text-decoration: none; font-weight: 700; letter-spacing: -.025em; }
.mark { width: 24px; height: 24px; display: inline-block; position: relative; border: 2px solid var(--green); border-radius: 50%; flex: 0 0 auto; }
.mark::after { content: ""; position: absolute; width: 12px; height: 2px; background: var(--green); right: -5px; top: 9px; box-shadow: -6px -6px 0 -0.5px var(--green), -6px 6px 0 -0.5px var(--green); }
nav { display: flex; align-items: center; gap: 30px; font-size: 14px; font-weight: 600; }
nav a { color: var(--ink); text-decoration: none; }
nav a:hover { color: var(--green); }
nav .nav-cta { border: 1px solid var(--ink); border-radius: 4px; padding: 8px 15px; }
.hero { padding-block: 100px 82px; }
.eyebrow { margin: 0 0 20px; color: var(--green); text-transform: uppercase; letter-spacing: .16em; font-family: "DM Mono", monospace; font-size: 12px; font-weight: 500; }
h1, h2, h3 { margin-top: 0; line-height: 1.09; letter-spacing: -.045em; }
h1 { max-width: 940px; margin-bottom: 28px; font-size: clamp(48px, 7.2vw, 92px); font-weight: 600; }
h1 em { font-family: Newsreader, Georgia, serif; color: var(--green); font-weight: 400; letter-spacing: -.035em; }
h2 { margin-bottom: 24px; font-size: clamp(32px, 4.2vw, 52px); font-weight: 600; }
h3 { font-size: 23px; font-weight: 600; }
.lede { max-width: 760px; margin: 0 0 34px; color: var(--muted); font-size: clamp(19px, 2vw, 23px); line-height: 1.55; }
.actions { display: flex; gap: 12px; flex-wrap: wrap; }
.button { display: inline-block; padding: 13px 20px; border: 1px solid var(--green); border-radius: 4px; text-decoration: none; font-size: 14px; font-weight: 700; }
.button.primary { background: var(--green); color: var(--white); }
.button.primary:hover { background: var(--green-dark); color: var(--white); }
.button.secondary { background: transparent; color: var(--green); }
.button.secondary:hover { background: var(--mint); }
.status { margin: 28px 0 0; color: var(--muted); font-size: 13px; }
.status span { color: #b48627; margin-right: 7px; }
.band { padding-block: 76px; background: #edf1e9; border-block: 1px solid var(--line); }
.two-col { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 84px; align-items: start; }
.prose { color: #354a46; }
.prose p:first-child { margin-top: 0; }
.prose p:last-child { margin-bottom: 0; }
.section { padding-block: 90px; }
.cards { display: grid; gap: 20px; margin-top: 44px; }
.cards.three { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.card { padding: 28px; background: var(--white); border: 1px solid var(--line); border-radius: 5px; }
.card-number { color: var(--green); font-family: "DM Mono", monospace; font-size: 12px; }
.card h3 { margin-top: 32px; }
.card p:last-child { color: var(--muted); font-size: 15px; margin-bottom: 0; }
.dark-section { background: var(--code); color: #f1f5ed; padding-block: 86px; }
.dark-section h2 { color: #f1f5ed; }
.dark-section p { color: #b7c9c2; }
.light { color: #b8d9c6; }
.text-link { display: inline-block; margin-top: 16px; font-weight: 700; }
.artifact-grid { align-items: center; }
.code-window { border: 1px solid #42605a; background: #0b2523; border-radius: 6px; overflow: hidden; box-shadow: 0 22px 50px rgba(0,0,0,.18); }
.code-top { display: flex; justify-content: space-between; padding: 12px 18px; border-bottom: 1px solid #31504a; color: #9ab5aa; font: 11px "DM Mono", monospace; text-transform: uppercase; letter-spacing: .1em; }
pre { margin: 0; padding: 26px 22px 14px; overflow-x: auto; font: 14px/1.9 "DM Mono", monospace; color: #e4eee6; }
code .muted { color: #9bb9ac; }
code .green { color: var(--lime); }
.code-caption { margin: 0; padding: 0 22px 20px; font-size: 11px; }
.truth-list > div { display: grid; grid-template-columns: 28px 1fr; gap: 12px; border-bottom: 1px solid var(--line); padding: 14px 0; }
.truth-list > div:first-child { padding-top: 0; }
.truth-list p { margin: 0; color: var(--muted); }
.truth-list strong { color: var(--ink); }
.yes { color: var(--green); }
.no { color: #8b6e40; }
.review-call .button { margin-top: 24px; }
footer { background: #e8ede4; border-top: 1px solid var(--line); padding-top: 56px; }
.footer-grid { display: grid; grid-template-columns: 2fr 1fr 1.5fr; gap: 60px; padding-bottom: 42px; }
.footer-grid p { color: var(--muted); font-size: 14px; }
.footer-grid a { display: block; margin: 7px 0; font-size: 14px; }
.footer-brand { font-size: 17px; }
.footer-heading { text-transform: uppercase; letter-spacing: .12em; font: 11px "DM Mono", monospace; color: var(--ink) !important; }
.footer-grid .fine { font-size: 12px; }
.footer-bottom { display: flex; justify-content: space-between; gap: 20px; border-top: 1px solid #cdd6ca; padding-block: 18px; }
.footer-bottom p { margin: 0; color: var(--muted); font-size: 11px; }

/* Interior pages */
.page-head { padding-block: 70px 50px; border-bottom: 1px solid var(--line); }
.page-head h1 { font-size: clamp(44px, 6vw, 70px); max-width: 900px; }
.page-head .lede { margin-bottom: 0; }
.content { padding-block: 60px 90px; }
.content.narrow { max-width: 850px; }
.content h2 { font-size: 34px; margin-top: 56px; }
.content h3 { margin-top: 32px; }
.content p, .content li { color: #354a46; }
.content li { margin-bottom: 8px; }
.notice { padding: 20px 24px; border-left: 4px solid #a5792c; background: #f3f0e4; margin: 28px 0; }
.notice p { margin: 0; }
.checklist { list-style: none; padding: 0; }
.checklist li { padding-left: 28px; position: relative; }
.checklist li::before { content: "□"; position: absolute; left: 0; color: var(--green); }
.artifact-list { display: grid; gap: 14px; margin-top: 32px; }
.artifact-item { display: grid; grid-template-columns: 1fr auto; gap: 24px; align-items: center; background: var(--white); border: 1px solid var(--line); padding: 22px 24px; border-radius: 5px; }
.artifact-item h3 { margin: 0 0 6px; font-size: 19px; }
.artifact-item p { margin: 0; font-size: 14px; }
.artifact-item .meta { color: var(--muted); font: 11px "DM Mono", monospace; text-transform: uppercase; }
.file-link { white-space: nowrap; font-size: 13px; font-weight: 700; }
details { border-bottom: 1px solid var(--line); padding: 16px 0; }
summary { cursor: pointer; font-weight: 700; color: var(--ink); }
details > div { padding: 14px 0; }
.small { font-size: 14px; }

@media (max-width: 800px) {
  .site-header { align-items: flex-start; }
  nav { gap: 16px; flex-wrap: wrap; justify-content: flex-end; }
  nav .nav-cta { display: none; }
  .two-col, .cards.three, .footer-grid { grid-template-columns: 1fr; gap: 28px; }
  .hero { padding-block: 66px 56px; }
  .band, .section, .dark-section { padding-block: 56px; }
  .footer-grid { gap: 20px; }
  .footer-bottom { flex-direction: column; gap: 4px; }
}
@media (max-width: 520px) {
  .wrap { width: min(calc(100% - 32px), var(--max)); }
  .site-header { padding-inline: 16px; flex-direction: column; gap: 14px; }
  nav { justify-content: flex-start; }
  h1 { font-size: 47px; }
  .artifact-item { grid-template-columns: 1fr; gap: 12px; }
}
@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } }
@media print {
  .site-header, footer, .actions, .button { display: none; }
  body { background: white; color: black; font-size: 11pt; }
  .wrap { width: 100%; }
  .hero, .section, .content { padding-block: 20px; }
  .dark-section { background: white; color: black; }
  .dark-section h2, .dark-section p { color: black; }
  a { color: black; }
}
